args.sparql:
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?film ?filmLabel ?director ?directorLabel ?birthDate WHERE {
  VALUES (?f1 ?f2) {(dbr:Goopy_Gyne_Bagha_Byne dbr:Halloween_Kills)}
  ?f1 dbo:director ?d1 .
  ?f2 dbo:director ?d2 .

  OPTIONAL { ?d1 dbo:birthDate ?b1. }
  OPTIONAL { ?d1 dbp:birthDate ?b1b. }
  OPTIONAL { ?d1 dbp:birth_date ?b1c. }

  OPTIONAL { ?d2 dbo:birthDate ?b2. }
  OPTIONAL { ?d2 dbp:birthDate ?b2b. }
  OPTIONAL { ?d2 dbp:birth_date ?b2c. }

  BIND(coalesce(?b1, ?b1b, ?b1c) AS ?dob1)
  BIND(coalesce(?b2, ?b2b, ?b2c) AS ?dob2)

  {
    FILTER(xsd:date(?dob1) < xsd:date(?dob2))
    BIND(?f1 AS ?film)
    BIND(?d1 AS ?director)
    BIND(?dob1 AS ?birthDate)
  }
  UNION
  {
    FILTER(xsd:date(?dob2) < xsd:date(?dob1))
    BIND(?f2 AS ?film)
    BIND(?d2 AS ?director)
    BIND(?dob2 AS ?birthDate)
  }

  OPTIONAL { ?film rdfs:label ?filmLabel . FILTER(lang(?filmLabel) = "en") }
  OPTIONAL { ?director rdfs:label ?directorLabel . FILTER(lang(?directorLabel) = "en") }
}
LIMIT 10

